// ---------------------------------------------------------------------------
// Evidence: every harness writes JSON lines to R7_SIM_EVIDENCE (if set).
// ---------------------------------------------------------------------------
func simRecord(t *testing.T, key string, value any) {
	t.Helper()
	b, _ := json.Marshal(map[string]any{"test": t.Name(), "key": key, "value": value, "at": time.Now().UTC()})
	t.Logf("R7_SIM %s", b)
	if path := os.Getenv("R7_SIM_EVIDENCE"); path != "" {
		f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
		if err == nil {
			_, _ = f.Write(append(b, '\n'))
			_ = f.Close()
		}
	}
}

// ---------------------------------------------------------------------------
// Development PKI (isolated per test; mirrors tools/certs).
// ---------------------------------------------------------------------------
type simPKI struct {
	dir    string // ca.crt + <id>.crt/.key for cloud-api and every device
	broker string // ca.crt + mosquitto.crt/.key
	ca     *x509.Certificate
	key    *ecdsa.PrivateKey
}

func writePEM(t *testing.T, path, kind string, der []byte) {
	t.Helper()
	if err := os.WriteFile(path, pem.EncodeToMemory(&pem.Block{Type: kind, Bytes: der}), 0o600); err != nil {
		t.Fatal(err)
	}
}

func newSimPKI(t *testing.T, root string) *simPKI {
	t.Helper()
	key, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	tmpl := &x509.Certificate{SerialNumber: big.NewInt(time.Now().UnixNano()), Subject: pkix.Name{CommonName: "R7 SIM-E2E Development CA"}, NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(72 * time.Hour), IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		t.Fatal(err)
	}
	ca, _ := x509.ParseCertificate(der)
	p := &simPKI{dir: filepath.Join(root, "certs"), broker: filepath.Join(root, "broker"), ca: ca, key: key}
	for _, d := range []string{p.dir, p.broker} {
		if err := os.MkdirAll(d, 0o700); err != nil {
			t.Fatal(err)
		}
		writePEM(t, filepath.Join(d, "ca.crt"), "CERTIFICATE", der)
	}
	p.issue(t, p.broker, "mosquitto", true)
	p.issue(t, p.dir, "cloud-api", false)
	return p
}

func (p *simPKI) issue(t *testing.T, dir, id string, server bool) {
	t.Helper()
	key, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	serial, _ := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 120))
	c := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: id}, NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(24 * time.Hour), KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}}
	if server {
		c.ExtKeyUsage = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}
		c.DNSNames = []string{"localhost"}
		c.IPAddresses = []net.IP{net.ParseIP("127.0.0.1")}
	}
	der, err := x509.CreateCertificate(rand.Reader, c, p.ca, &key.PublicKey, p.key)
	if err != nil {
		t.Fatal(err)
	}
	writePEM(t, filepath.Join(dir, id+".crt"), "CERTIFICATE", der)
	kb, _ := x509.MarshalPKCS8PrivateKey(key)
	writePEM(t, filepath.Join(dir, id+".key"), "PRIVATE KEY", kb)
}

// ---------------------------------------------------------------------------
// Real Mosquitto.
// ---------------------------------------------------------------------------
func freePort(t *testing.T) int {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

func startMosquitto(t *testing.T, root string, pki *simPKI, acl string) (int, *os.Process) {
	t.Helper()
	bin := os.Getenv("MOSQUITTO_BIN")
	if bin == "" {
		t.Fatal("MOSQUITTO_BIN required when R7_SIM_E2E=1")
	}
	port := freePort(t)
	aclPath := filepath.Join(root, "acl")
	if err := os.WriteFile(aclPath, []byte(acl), 0o600); err != nil {
		t.Fatal(err)
	}
	conf := fmt.Sprintf(`listener %d 127.0.0.1
protocol mqtt
allow_anonymous false
require_certificate true
use_identity_as_username true
cafile %s
certfile %s
keyfile %s
tls_version tlsv1.2
acl_file %s
persistence false
max_queued_messages 1000
message_size_limit 32768
log_dest file %s
log_type error
log_type warning
log_type notice
`, port, filepath.Join(pki.broker, "ca.crt"), filepath.Join(pki.broker, "mosquitto.crt"), filepath.Join(pki.broker, "mosquitto.key"), aclPath, filepath.Join(root, "mosquitto.log"))
	confPath := filepath.Join(root, "mosquitto.conf")
	if err := os.WriteFile(confPath, []byte(conf), 0o600); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(bin, "-c", confPath)
	cmd.Stdout, cmd.Stderr = io.Discard, io.Discard
	if err := cmd.Start(); err != nil {
		t.Fatal("mosquitto start", err)
	}
	t.Cleanup(func() {
		// SIGTERM first: a wrapper (docker run, sig-proxy) forwards it and removes its container.
		_ = cmd.Process.Signal(syscall.SIGTERM)
		done := make(chan struct{})
		go func() { _, _ = cmd.Process.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			_ = cmd.Process.Kill()
			<-done
		}
	})
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if c, err := net.DialTimeout("tcp", fmt.Sprintf("127.0.0.1:%d", port), 200*time.Millisecond); err == nil {
			_ = c.Close()
			return port, cmd.Process
		}
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatal("mosquitto did not listen")
	return 0, nil
}

// ---------------------------------------------------------------------------
// Fault-injection proxy: one per device, so faults are attributed to one target.
// ---------------------------------------------------------------------------
type simProxy struct {
	ln       net.Listener
	target   string
	mu       sync.Mutex
	conns    []net.Conn
	refusing atomic.Bool
	drops    atomic.Int64
	accepts  atomic.Int64 // TCP connections relayed to the broker (each reconnect is one more)
}

func newSimProxy(t *testing.T, target string) *simProxy {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	p := &simProxy{ln: ln, target: target}
	go func() {
		for {
			c, err := ln.Accept()
			if err != nil {
				return
			}
			if p.refusing.Load() {
				_ = c.Close()
				continue
			}
			up, err := net.Dial("tcp", target)
			if err != nil {
				_ = c.Close()
				continue
			}
			p.mu.Lock()
			p.conns = append(p.conns, c, up)
			p.mu.Unlock()
			p.accepts.Add(1)
			go func() { _, _ = io.Copy(up, c); _ = up.Close() }()
			go func() { _, _ = io.Copy(c, up); _ = c.Close() }()
		}
	}()
	t.Cleanup(func() { _ = ln.Close(); p.dropAll() })
	return p
}

func (p *simProxy) url() string { return "tls://" + p.ln.Addr().String() }

// dropAll closes the TCP connections abruptly (no MQTT DISCONNECT): the broker sees a lost client.
func (p *simProxy) dropAll() {
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, c := range p.conns {
		_ = c.Close()
	}
	p.conns = nil
	p.drops.Add(1)
}

// ---------------------------------------------------------------------------
// The environment.
// ---------------------------------------------------------------------------
type simEnv struct {
	t         *testing.T
	ctx       context.Context
	db        *sql.DB
	root      string
	pki       *simPKI
	broker    string
	mosquitto *os.Process
	manifest  contract.FleetManifest
	req       runtimeidentity.Request
	provider  *testsupport.OIDCProvider
	server    *httptest.Server
	handler   http.Handler
	store     *device.Store
	leases    *session.Manager

	cloudMu     sync.Mutex
	cloudCancel context.CancelFunc
	cloud       *runtimeLoop

	devMu   sync.Mutex
	devices map[string]*simDevice
	proxies map[string]*simProxy
	assets  map[string]string // project → asset ids (in order)
}

type simDevice struct {
	cancel context.CancelFunc
	done   chan error
}

func simEnabled(t *testing.T) {
	t.Helper()
	if os.Getenv("R7_SIM_E2E") != "1" {
		t.Skip("R7 SIM-E2E runs only with R7_SIM_E2E=1 (real Mosquitto + PostgreSQL)")
	}
}

type simSpec struct {
	project string
	runtime string
	source  string // SIMULATION / TEST
	bind    bool   // bind an installed PLC Equipment to the runtime
}

// newSimEnv builds projects, assets (through the business API), registers the runtimes with the
// controlled runtime-identity tool, issues device certificates, generates the ACL from the Fleet,
// and starts Mosquitto, the cloud runtime and the BFF.
func newSimEnv(t *testing.T, ttl, grace time.Duration, specs []simSpec) *simEnv {
	t.Helper()
	simEnabled(t)
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	e := &simEnv{t: t, ctx: ctx, db: testsupport.Database(t), root: t.TempDir(), devices: map[string]*simDevice{}, proxies: map[string]*simProxy{}, assets: map[string]string{}}
	if _, err := e.db.Exec(`INSERT INTO equipment_types(type_code,display_name,domain) VALUES('PLC','PLC 控制器','CONTROL') ON CONFLICT DO NOTHING`); err != nil {
		t.Fatal(err)
	}
	e.req = runtimeidentity.Request{TenantId: "demo"}
	projects := map[string]bool{}
	for i, s := range specs {
		if !projects[s.project] {
			projects[s.project] = true
			if _, err := e.db.Exec(`INSERT INTO projects(id,tenant_id,name,lifecycle) VALUES($1,'demo',$1,'PLANNED') ON CONFLICT DO NOTHING`, s.project); err != nil {
				t.Fatal(err)
			}
		}
		code := fmt.Sprintf("R7SIM-%02d", i+1)
		a, err := asset.CreateAsset(ctx, e.db, contract.AssetMasterData{ProjectId: s.project, AssetType: "CRANE", AssetCode: &code, DisplayName: s.runtime}, "r7-sim", "r7-sim", "")
		if err != nil {
			t.Fatal(err)
		}
		e.assets[s.runtime] = a.Id
		entry := runtimeidentity.Entry{RuntimeDeviceId: s.runtime, ProjectId: s.project, AssetDeviceId: a.Id, SourceMode: s.source}
		if s.bind {
			eq, err := asset.CreateEquipment(ctx, e.db, contract.EquipmentInstallation{AssetId: a.Id, EquipmentCode: "PLC-" + s.runtime, TypeCode: "PLC", Criticality: "HIGH"}, json.RawMessage(`{}`), "r7-sim", "r7-sim", "")
			if err != nil {
				t.Fatal(err)
			}
			entry.EquipmentInstallationId = &eq.Id
		}
		e.req.Entries = append(e.req.Entries, entry)
	}
	// No specs: the explicit empty Fleet of a zero-business start (R8).
	e.manifest = contract.FleetManifest{TenantId: "demo", Devices: []contract.RuntimeDescriptor{}}
	if len(specs) > 0 {
		plan, err := runtimeidentity.PlanRegistration(ctx, e.db, e.req)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := runtimeidentity.Apply(ctx, e.db, e.req, plan.Digest, "r7-sim-operator", "r7-sim-register"); err != nil {
			t.Fatal(err)
		}
		e.manifest = runtimeidentity.Fleet(e.req)
	}
	if err := fleet.Validate(e.manifest, false); err != nil {
		t.Fatal(err)
	}
	if err := device.ValidateFleet(ctx, e.db, e.manifest); err != nil {
		t.Fatal("registered runtimes do not match the Fleet:", err)
	}
	e.pki = newSimPKI(t, e.root)
	for _, s := range specs {
		e.pki.issue(t, e.pki.dir, s.runtime, false)
	}
	acl, err := fleet.ACL(e.manifest)
	if err != nil {
		t.Fatal(err)
	}
	port, mosq := startMosquitto(t, e.root, e.pki, acl)
	e.broker, e.mosquitto = fmt.Sprintf("127.0.0.1:%d", port), mosq

	e.store, err = device.New(ctx, e.db)
	if err != nil {
		t.Fatal(err)
	}
	e.leases = session.New(e.db, ttl, grace)
	e.startCloud()
	t.Cleanup(e.stopCloud)

	e.provider = testsupport.NewOIDC(t)
	var delegate atomic.Value
	e.server = httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { delegate.Load().(http.Handler).ServeHTTP(w, r) }))
	t.Cleanup(e.server.Close)
	absolute := simSessionTTL(t)
	manager, err := webauth.New(ctx, e.db, webauth.Config{PublicURL: e.server.URL, Issuer: e.provider.Server.URL, ClientID: testsupport.OIDCClient, ClientSecret: []byte(testsupport.OIDCSecret), ServerSecret: []byte(strings.Repeat("r7-sim-server-key-", 3)), AbsoluteTTL: absolute, IdleTTL: min(30*time.Minute, absolute), HTTPClient: e.provider.Server.Client()})
	if err != nil {
		t.Fatal(err)
	}
	active := func(v contract.Shadow) bool {
		return fleet.Allows(e.manifest, contract.Envelope{TenantId: v.TenantId, ProjectId: v.ProjectId, DeviceId: v.DeviceId})
	}
	list := func() []contract.Shadow {
		out := []contract.Shadow{}
		for _, v := range e.store.List() {
			if active(v) {
				out = append(out, v)
			}
		}
		return out
	}
	var ws, dbErrors atomic.Int64
	h := &apiHandler{config: platform.Config{Env: "production"}, db: e.db, store: e.store, leases: e.leases, active: active, list: list, logger: platform.Logger("r7-sim"), wsClients: &ws, dbErrors: &dbErrors, web: manager, ops: operations.Config{StaleAfter: operations.DefaultStaleAfter, MaxFutureSkew: operations.DefaultMaxFutureSkew}}
	mux := http.NewServeMux()
	if err := h.register(mux); err != nil {
		t.Fatal(err)
	}
	e.handler = mux
	delegate.Store(http.Handler(mux))
	t.Cleanup(e.stopDevices)
	return e
}

// reloadBrokerACL makes the broker re-read its ACL file (SIGHUP, as on the site); connections stay.
func (e *simEnv) reloadBrokerACL() {
	e.t.Helper()
	if err := e.mosquitto.Signal(syscall.SIGHUP); err != nil {
		e.t.Fatal("SIGHUP mosquitto:", err)
	}
	time.Sleep(500 * time.Millisecond)
}

func newRecorder() *httptest.ResponseRecorder { return httptest.NewRecorder() }

func (e *simEnv) startCloud() {
	e.cloudMu.Lock()
	defer e.cloudMu.Unlock()
	ctx, cancel := context.WithCancel(e.ctx)
	c := platform.Config{MQTTURL: "tls://" + e.broker, CertDir: e.pki.dir, WillDelay: 5}
	rt, err := startRuntime(ctx, c, e.db, e.manifest, e.store, e.leases, platform.Logger("r7-sim-cloud"))
	if err != nil {
		cancel()
		e.t.Fatal("cloud runtime", err)
	}
	e.cloud, e.cloudCancel = rt, cancel
	e.until("cloud MQTT up", 15*time.Second, func() bool { return rt.mqttUp.Load() })
}

func (e *simEnv) stopCloud() {
	e.cloudMu.Lock()
	defer e.cloudMu.Unlock()
	if e.cloudCancel == nil {
		return
	}
	done, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	_ = e.cloud.broker.CM.Disconnect(done)
	cancel()
	e.cloudCancel()
	e.cloudCancel = nil
}

func (e *simEnv) startDevice(id, scenario string) {
	e.t.Helper()
	e.devMu.Lock()
	defer e.devMu.Unlock()
	p, ok := e.proxies[id]
	if !ok {
		p = newSimProxy(e.t, e.broker)
		e.proxies[id] = p
	}
	var desc fleet.Device
	for _, d := range fleet.Devices(e.manifest) {
		if d.RuntimeDeviceId == id {
			desc = d
		}
	}
	ctx, cancel := context.WithCancel(e.ctx)
	d := &simDevice{cancel: cancel, done: make(chan error, 1)}
	c := platform.Config{MQTTURL: p.url(), CertDir: e.pki.dir, DataDir: filepath.Join(e.root, "spool"), Scenario: scenario, WillDelay: 5}
	go func() { d.done <- runner.RunDevice(ctx, c, desc) }()
	e.devices[id] = d
}

// stopDevice is a graceful Agent stop (DEATH GRACEFUL).
func (e *simEnv) stopDevice(id string) {
	e.devMu.Lock()
	d := e.devices[id]
	delete(e.devices, id)
	e.devMu.Unlock()
	if d == nil {
		return
	}
	d.cancel()
	select {
	case err := <-d.done:
		if err != nil {
			e.t.Errorf("device %s stopped with %v", id, err)
		}
	case <-time.After(10 * time.Second):
		e.t.Errorf("device %s did not stop", id)
	}
}

func (e *simEnv) stopDevices() {
	e.devMu.Lock()
	ids := []string{}
	for id := range e.devices {
		ids = append(ids, id)
	}
	e.devMu.Unlock()
	for _, id := range ids {
		e.stopDevice(id)
	}
}

func (e *simEnv) until(label string, timeout time.Duration, f func() bool) {
	e.t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if f() {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}
	e.t.Fatalf("timed out after %s: %s", timeout, label)
}

func (e *simEnv) shadowDB(id string) (contract.Shadow, bool) {
	var b []byte
	if err := e.db.QueryRow(`SELECT payload_json FROM device_shadow WHERE device_id=$1`, id).Scan(&b); err != nil {
		return contract.Shadow{}, false
	}
	var v contract.Shadow
	_ = json.Unmarshal(b, &v)
	return v, true
}

func (e *simEnv) connected(id string) bool {
	v, ok := e.shadowDB(id)
	return ok && v.Presence.Connectivity == "MQTT_CONNECTED"
}

// ---------------------------------------------------------------------------
// Users, HTTP and WebSocket through the real BFF.
// ---------------------------------------------------------------------------
type simUser struct {
	id     string
	cookie *http.Cookie
	csrf   string
}

func (e *simEnv) user(name, project, role string) *simUser {
	e.t.Helper()
	if err := identity.Bind(e.ctx, e.db, "u-"+name, e.provider.Server.URL, "sub-"+name, "R7 "+name, true, auditlog.Event{Actor: "r7-sim"}); err != nil {
		e.t.Fatal(err)
	}
	if project != "" {
		if err := identity.ChangeGrant(e.ctx, e.db, "u-"+name, project, role, false, auditlog.Event{Actor: "r7-sim"}); err != nil {
			e.t.Fatal(err)
		}
	}
	e.provider.Set(testsupport.OIDCScenario{Subject: "sub-" + name})
	cookie, s := testsupport.Login(e.t, e.handler, e.provider, e.server.URL)
	return &simUser{id: "u-" + name, cookie: cookie, csrf: s.CsrfToken}
}

func (e *simEnv) call(u *simUser, method, path string, out any) int {
	e.t.Helper()
	r := httptest.NewRequest(method, e.server.URL+path, nil)
	if u != nil {
		r.AddCookie(u.cookie)
		if stateChanging(method) {
			r.Header.Set("Origin", e.server.URL)
			r.Header.Set("X-CSRF-Token", u.csrf)
		}
	}
	w := httptest.NewRecorder()
	e.handler.ServeHTTP(w, r)
	if out != nil && w.Code < 300 {
		_ = json.Unmarshal(w.Body.Bytes(), out)
	}
	return w.Code
}

func (e *simEnv) dialStream(u *simUser, id string) (*websocket.Conn, *http.Response, error) {
	ctx, cancel := context.WithTimeout(e.ctx, 5*time.Second)
	defer cancel()
	wsURL := "wss" + strings.TrimPrefix(e.server.URL, "https") + "/api/v1/devices/" + id + "/stream"
	h := http.Header{}
	h.Set("Origin", e.server.URL)
	h.Set("Cookie", u.cookie.Name+"="+u.cookie.Value)
	return websocket.Dial(ctx, wsURL, &websocket.DialOptions{HTTPClient: e.server.Client(), HTTPHeader: h})
}

// ---------------------------------------------------------------------------
// Raw MQTT client with a device's own certificate (abuse / ordering tests).
// ---------------------------------------------------------------------------
type rawClient struct {
	c    *paho.Client
	conn net.Conn
}

func (e *simEnv) raw(id, certDir string) (*rawClient, error) {
	cfg, err := platform.TLS(certDir, id)
	if err != nil {
		return nil, err
	}
	conn, err := tls.DialWithDialer(&net.Dialer{Timeout: 3 * time.Second}, "tcp", e.broker, cfg)
	if err != nil {
		return nil, err
	}
	c := paho.NewClient(paho.ClientConfig{ClientID: id + "-raw", Conn: packets.NewThreadSafeConn(conn)})
	ctx, cancel := context.WithTimeout(e.ctx, 5*time.Second)
	defer cancel()
	ack, err := c.Connect(ctx, &paho.Connect{ClientID: id, CleanStart: true, KeepAlive: 10})
	if err != nil || ack.ReasonCode >= 0x80 {
		_ = conn.Close()
		if err == nil {
			err = fmt.Errorf("connack 0x%x", ack.ReasonCode)
		}
		return nil, err
	}
	return &rawClient{c: c, conn: conn}, nil
}

func (r *rawClient) close() { _ = r.c.Disconnect(&paho.Disconnect{}); _ = r.conn.Close() }

func (r *rawClient) publish(ctx context.Context, topic string, payload []byte) (byte, error) {
	c, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	res, err := r.c.Publish(c, &paho.Publish{Topic: topic, QoS: 1, Payload: payload})
	if err != nil {
		if res != nil {
			return res.ReasonCode, err
		}
		return 0xff, err
	}
	return res.ReasonCode, nil
}

func envelopeFor(id, project, kind string, bootID string, bootSeq, seq int64, payload any) contract.Envelope {
	return contract.WithPayload(contract.Envelope{SchemaVersion: 1, MessageId: platform.ID(), TenantId: "demo", ProjectId: project, DeviceId: id, BootId: bootID, BootSeq: bootSeq, Sequence: seq, SentAt: time.Now().UTC(), Kind: kind}, payload)
}

// simSoakDuration is the hold time of TestR7Sim20DevicesSoak (default 90 s; R7_SIM_SOAK_SECONDS /
// R7_SIM_SOAK_MINUTES override; minutes win).
func simSoakDuration() time.Duration {
	d := 90 * time.Second
	if v, err := strconv.Atoi(os.Getenv("R7_SIM_SOAK_SECONDS")); err == nil && v > 0 {
		d = time.Duration(v) * time.Second
	}
	if v, err := strconv.Atoi(os.Getenv("R7_SIM_SOAK_MINUTES")); err == nil && v > 0 {
		d = time.Duration(v) * time.Minute
	}
	return d
}

// simSessionTTL is the web-session absolute lifetime of the TEST harness only (production keeps
// its configured AbsoluteSeconds/IdleSeconds). A soak must outlive the login made before it starts:
// soak duration + 30 min margin, at least 1 h. R7_SIM_SESSION_TTL_SECONDS (test-only) forces a
// value to reproduce an expiring session (a 401 on renew still fails the soak — never swallowed).
func simSessionTTL(t *testing.T) time.Duration {
	if v, err := strconv.Atoi(os.Getenv("R7_SIM_SESSION_TTL_SECONDS")); err == nil && v > 0 {
		t.Logf("R7_SIM session TTL forced to %ds", v)
		return time.Duration(v) * time.Second
	}
	return max(time.Hour, simSoakDuration()+30*time.Minute)
}

// repoRoot finds the repository root (the directory whose go.mod declares this module) from the
// working directory upwards. `go test` runs in the package directory, while the CI gate runs the
// precompiled test binary (`go test -c`) from the repository root: both must resolve the same path.
func repoRoot(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	for {
		if b, err := os.ReadFile(filepath.Join(dir, "go.mod")); err == nil && strings.Contains(string(b), "module github.com/guolichen007/crane-operations-platform\n") {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatal("repository root (go.mod of crane-operations-platform) not found above the working directory")
		}
		dir = parent
	}
}

// R8: a certificate issued by deploy/scripts/sim-cert.sh (openssl, host only) from the broker's CA
// connects to the real broker and is scoped by the generated ACL like any Agent identity.
func TestR8SimCertScriptIssuesUsableIdentity(t *testing.T) {
	simEnabled(t)
	if _, err := exec.LookPath("openssl"); err != nil {
		t.Skip("openssl required")
	}
	e := newSimEnv(t, 30*time.Second, 5*time.Second, []simSpec{{project: "R8-C", runtime: "SIM-R8-CERT", source: "SIMULATION"}})
	caDir := filepath.Join(e.root, "ca")
	if err := os.MkdirAll(caDir, 0o700); err != nil {
		t.Fatal(err)
	}
	// The harness CA (the broker trusts it) in the layout the script expects.
	b, _ := os.ReadFile(filepath.Join(e.pki.dir, "ca.crt"))
	_ = os.WriteFile(filepath.Join(caDir, "ca.crt"), b, 0o600)
	kb, _ := x509.MarshalPKCS8PrivateKey(e.pki.key)
	writePEM(t, filepath.Join(caDir, "ca.key"), "PRIVATE KEY", kb)
	out := filepath.Join(e.root, "sim-out")
	script := filepath.Join(repoRoot(t), "deploy", "scripts", "sim-cert.sh")
	cmd := exec.Command("bash", script, "issue", "--ca-dir", caDir, "--out", out, "--id", "SIM-R8-CERT", "--days", "2")
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("sim-cert.sh: %v %s", err, b)
	}
	if _, err := os.Stat(filepath.Join(out, "ca.key")); err == nil {
		t.Fatal("CA key copied into the simulator directory")
	}
	c, err := e.raw("SIM-R8-CERT", out)
	if err != nil {
		t.Fatal("script-issued certificate rejected by the broker:", err)
	}
	defer c.close()
	own, _ := contract.Topic("demo", "R8-C", "SIM-R8-CERT", "heartbeat")
	b2, _ := json.Marshal(envelopeFor("SIM-R8-CERT", "R8-C", "HEARTBEAT", "b", 1, 1, contract.HeartbeatPayload{EdgeHealth: "EDGE_HEALTHY", ControllerHealth: "CONTROLLER_HEALTHY", SensorHealth: "HEALTHY"}))
	if rc, err := c.publish(e.ctx, own, b2); err != nil || rc >= 0x80 {
		t.Fatalf("own topic publish rc=%d err=%v", rc, err)
	}
	other, _ := contract.Topic("demo", "R8-C", "SIM-R8-OTHER", "heartbeat")
	if rc, _ := c.publish(e.ctx, other, b2); rc != 0x87 {
		t.Fatalf("foreign topic publish rc=0x%x, want 0x87 not authorized", rc)
	}
	simRecord(t, "SIM_CERT_SCRIPT", "openssl-issued SIM certificate accepted by broker; ACL scoped; CA key not in output")
}

// The harness session must outlive the soak (the 60-minute server soak got 401 on renew with the old
// fixed 1 h lifetime: login happens before the hold starts). Pure rule check; no broker/DB needed.
func TestR8SimSessionTTLOutlivesSoak(t *testing.T) {
	for _, c := range []struct{ minutes, seconds string }{{"", ""}, {"", "90"}, {"60", ""}, {"120", ""}} {
		t.Setenv("R7_SIM_SOAK_MINUTES", c.minutes)
		t.Setenv("R7_SIM_SOAK_SECONDS", c.seconds)
		t.Setenv("R7_SIM_SESSION_TTL_SECONDS", "")
		soak, ttl := simSoakDuration(), simSessionTTL(t)
		if ttl < soak+30*time.Minute || ttl < time.Hour {
			t.Fatalf("soak %s: session TTL %s does not cover soak + 30 min", soak, ttl)
		}
		if ttl > 24*time.Hour {
			t.Fatalf("soak %s: session TTL %s exceeds webauth maximum", soak, ttl)
		}
	}
}
